window.__quizData['google_search'].questions.push(
  { q: 'What is the minimum number of users a Remarketing List must have before being used with a Remarketing List for Search Ads campaign?', options: ['100 users','500 users','1,000 users','10,000 users'], correct: 2, explanation: 'RLSA requires a minimum of 1,000 users on the list before it can be used for targeting. This threshold ensures statistically significant audience data for optimization.', tags: ['Google-Ads','Search','RLSA','remarketing'] },
  { q: 'What search network text ad component provides up to three fields of 30 characters each?', options: ['The website URL component','The conversion component','The description component','The headline component'], correct: 3, explanation: 'Responsive Search Ads support up to 15 headlines, but the traditional text ad headline allowed up to 3 fields of 30 characters each (Headline 1, 2, 3).', tags: ['Google-Ads','Search','RSA','headline','caracteres'] },
  { q: 'When visibility is the campaign goal, which bidding strategy should an advertiser choose?', options: ['Enhanced cost-per-click (eCPC)','Maximize Conversions','Maximize clicks','Target impression share'], correct: 3, explanation: 'Target Impression Share is the only bidding strategy specifically designed for visibility — it aims to show your ad on a specific percentage of eligible impressions at the top of the page.', tags: ['Google-Ads','Search','Target-Impression-Share','visibilidade'] },
  { q: 'What is the maximum number of ad extensions that can show for a particular query at any given time?', options: ['1','2','3','4'], correct: 3, explanation: 'Up to 4 ad extensions can show simultaneously for a single ad — though Google selects which extensions show based on their expected performance for each auction.', tags: ['Google-Ads','Search','extensions','máximo'] },
  { q: 'Jim has a Google Search ad with a bid of $5. Two advertisers bid $2.50 and $2. How much does Jim pay for first position?', options: ['$5','$4.50','$2.50','$2.51'], correct: 3, explanation: 'In a second-price auction, the winner pays just above the next highest bid. Jim wins with $5, but pays $2.51 (the second-place bid of $2.50 + $0.01). This is how Google Search auctions work.', tags: ['Google-Ads','Search','leilão','segundo-preço','lance'] },
  { q: 'When should you use Remarketing Lists for Search Ads (RLSA)?', options: ['To identify loyal customers and expand reach to those that resemble them','To reach new customers sharing characteristics of your remarketing segments','To reach people based on advanced demographic criteria','To reach people who have already engaged with your website in the past'], correct: 3, explanation: 'RLSA targets people who have previously visited your website or app while they search on Google — allowing you to tailor bids, ads, and keywords for this high-value audience.', tags: ['Google-Ads','Search','RLSA','remarketing'] },
  { q: 'What ad extension is ONLY available as a fully automated ad extension?', options: ['Message extension','App extension','Price extension','Seller rating extension'], correct: 3, explanation: 'Seller ratings are fully automated — Google aggregates ratings from review sources and automatically shows them when thresholds are met. Advertisers cannot manually create or control them.', tags: ['Google-Ads','Search','Seller-Rating','automated-extension'] },
  { q: 'How many headlines can be included in a single Responsive Search Ad?', options: ['Up to 5 headlines','Up to 25 headlines','Up to 50 headlines','Up to 15 headlines'], correct: 3, explanation: 'RSAs support up to 15 headlines and 4 descriptions. Google\'s ML tests combinations and learns which perform best. At least 3 headlines show in any given auction (pinning can control placement).', tags: ['Google-Ads','Search','RSA','headlines','15'] },
  { q: 'Which Dynamic Search Ads option allows grouping web pages under custom labels?', options: ['URL filtering','Categories','Landing pages from standard ad groups','Page feeds'], correct: 3, explanation: 'Page feeds let advertisers upload a spreadsheet of URLs with custom labels, enabling granular control over which pages are targeted by DSA — ideal for large e-commerce sites.', tags: ['Google-Ads','Search','DSA','page-feeds','Dynamic-Search'] },
  { q: 'What does the Performance Planner automatically do?', options: ['Uses machine learning to target new demographics','Sets your ad budget for maximum growth','Recommends the perfect ad structure for your budget','Forecasts how current campaigns will perform in the future'], correct: 3, explanation: 'Performance Planner uses Google\'s machine learning (powered by billions of weekly searches) to forecast how campaigns will perform at different spend levels — helping optimize budget allocation.', tags: ['Google-Ads','Search','Performance-Planner','forecast'] }
);

